-- The `.reference` file of this test was written by hand, by deducing the expected output.
-- It was NOT generated by running a server and may need to be regenerated.
--
-- Filters on `LowCardinality` columns: `x IN (...)`, `x NOT IN (...)`, `x = 'a'` and `x != 'a'` return
-- `LowCardinality(UInt8)`. A block whose filter is false (or true) in every row is detected
-- without converting the filter to a full column. Each query lists the ids that pass the filter.
-- Blocks of 4 rows make some blocks fully matching, some not matching at all and keep the
-- dictionary of the part, which has keys that the block does not reference.

SET max_block_size = 4;
-- Move the WHERE conditions to `FilterTransform`, the PREWHERE ones are explicit.
SET optimize_move_to_prewhere = 0;

DROP TABLE IF EXISTS t_lc_filter;
DROP TABLE IF EXISTS t_lc_filter_mem;

CREATE TABLE t_lc_filter (id UInt32, s LowCardinality(String), sn LowCardinality(Nullable(String)), p String)
ENGINE = MergeTree ORDER BY id SETTINGS index_granularity = 4;

INSERT INTO t_lc_filter
SELECT number + 1, multiIf(number < 4, 'a', number < 8, 'b', 'c'), multiIf(number < 4, 'a', number < 8, NULL, 'c'), concat('p', toString(number + 1))
FROM numbers(12);

CREATE TABLE t_lc_filter_mem (id UInt32, s LowCardinality(String), sn LowCardinality(Nullable(String)), p String) ENGINE = Memory;
INSERT INTO t_lc_filter_mem SELECT * FROM t_lc_filter;

-- String column
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a', 'b');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a', 'b', 'c');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN ('a', 'b', 'c');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s = 'b';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s = 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s != 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s != 'b';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE 'b' = s;
-- Sets with and without the empty string (the default value, always present in the dictionary)
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('', 'b');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN ('');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s = '';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s != '';
-- LowCardinality(Nullable(String)): a NULL never passes IN, NOT IN, = or !=
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('a', 'c');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('a', 'c');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn = 'c';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn = 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn != 'c';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn != 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('');
-- transform_null_in: NULL is an ordinary value
SET transform_null_in = 1;
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('a', NULL);
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('a', NULL);
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn NOT IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE sn IN ('z');
SET transform_null_in = 0;
-- PREWHERE
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s NOT IN ('a', 'b');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE sn NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE sn IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s = 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s != 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter PREWHERE s != 'b' WHERE id > 2;
-- Tuples (the result is not LowCardinality, the filter must behave as before)
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE (s, id) IN (('a', 2), ('c', 10));
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE (s, id) NOT IN (('a', 2), ('c', 10));
-- Sets from subqueries
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN (SELECT 'b');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN (SELECT 'b');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN (SELECT 'z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN (SELECT 'a' WHERE 0);
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s NOT IN (SELECT 'a' WHERE 0);
-- Combinations
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a') AND id > 2;
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a') OR s IN ('c');
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE NOT (s IN ('a'));
SELECT arraySort(groupArray(id)) FROM t_lc_filter WHERE s IN ('a', 'z') AND sn NOT IN ('z');
-- The filter expression used as a regular value keeps its type and its values
SELECT toTypeName(s IN ('a')), toTypeName(s = 'a') FROM t_lc_filter LIMIT 1;
SELECT countIf(s IN ('a')), countIf(s NOT IN ('a')), countIf(s = 'z') FROM t_lc_filter;
SELECT id, s IN ('a') AS f FROM t_lc_filter ORDER BY id;
SELECT s IN ('a') AS g, count() FROM t_lc_filter GROUP BY g ORDER BY g;
-- Memory table: blocks of max_block_size rows share one dictionary that holds every key
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s NOT IN ('a');
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s = 'b';
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE s != 'z';
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE sn NOT IN ('z');
SELECT arraySort(groupArray(id)) FROM t_lc_filter_mem WHERE sn IN ('z');

DROP TABLE t_lc_filter;
DROP TABLE t_lc_filter_mem;
